import java.io.*;import java.util.*;
public class Main{
 static class F{byte[] b=new byte[65536];int p,z;int read()throws Exception{if(p==z){z=System.in.read(b);p=0;if(z<0)return -1;}return b[p++];}int next()throws Exception{int c,v=0;do{c=read();}while(c<=32&&c>=0);while(c>32){v=v*10+c-48;c=read();}return v;}}
 static int[][] up;static int[] depth,color,freq;static boolean[] active;static int total;static long pairs;
 static int lca(int a,int b){if(depth[a]<depth[b]){int t=a;a=b;b=t;}int d=depth[a]-depth[b];for(int j=0;d>0;j++,d>>=1)if((d&1)>0)a=up[j][a];if(a==b)return a;for(int j=up.length-1;j>=0;j--)if(up[j][a]!=up[j][b]){a=up[j][a];b=up[j][b];}return up[0][a];}
 static void toggle(int u){int c=color[u];if(active[u]){total--;freq[c]--;pairs-=total-freq[c];}else{pairs+=total-freq[c];total++;freq[c]++;}active[u]=!active[u];}
 public static void main(String[] args)throws Exception{F in=new F();StringBuilder out=new StringBuilder();int t=in.next();while(t-->0){int n=in.next(),q=in.next();color=new int[n];for(int i=0;i<n;i++)color[i]=in.next();int[] head=new int[n],to=new int[2*n-2],next=new int[2*n-2];Arrays.fill(head,-1);int e=0;for(int i=1;i<n;i++){int a=in.next()-1,b=in.next()-1;to[e]=b;next[e]=head[a];head[a]=e++;to[e]=a;next[e]=head[b];head[b]=e++;}depth=new int[n];up=new int[18][n];int[] enter=new int[n],exit=new int[n],tour=new int[2*n],stack=new int[2*n];int top=0,clock=0;stack[top++]=0;up[0][0]=0;while(top>0){int u=stack[--top];if(u<0){u=~u;exit[u]=clock;tour[clock++]=u;continue;}enter[u]=clock;tour[clock++]=u;stack[top++]=~u;for(int j=head[u];j!=-1;j=next[j]){int v=to[j];if(v==up[0][u])continue;up[0][v]=u;depth[v]=depth[u]+1;stack[top++]=v;}}for(int j=1;j<18;j++)for(int i=0;i<n;i++)up[j][i]=up[j-1][up[j-1][i]];int[] ls=new int[q],rs=new int[q],extra=new int[q];long[] order=new long[q],ans=new long[q];int bs=Math.max(1,(int)(2*n/Math.sqrt(q)));for(int i=0;i<q;i++){int a=in.next()-1,b=in.next()-1;if(enter[a]>enter[b]){int v=a;a=b;b=v;}int c=lca(a,b);if(c==a){ls[i]=enter[a];extra[i]=-1;}else{ls[i]=exit[a];extra[i]=c;}rs[i]=enter[b];int block=ls[i]/bs,r=(block%2==0?rs[i]:2*n-rs[i]);order[i]=(((long)block*(2*n+1)+r)<<20)|i;}Arrays.sort(order);active=new boolean[n];freq=new int[n+1];total=0;pairs=0;int l=0,r=-1;for(long key:order){int i=(int)(key&((1<<20)-1));while(l>ls[i])toggle(tour[--l]);while(r<rs[i])toggle(tour[++r]);while(l<ls[i])toggle(tour[l++]);while(r>rs[i])toggle(tour[r--]);if(extra[i]>=0)toggle(extra[i]);ans[i]=pairs;if(extra[i]>=0)toggle(extra[i]);}for(long v:ans)out.append(v).append('\n');}System.out.print(out);}
}